#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.11.0"

MODIFIED_B64 = {'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/io_runtime.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/repository.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/ComputerVision.css': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64 = {'backend/app/services/vision_app/automation_manager.py': '', 'backend/app/services/vision_app/automation_models.py': '', 'backend/app/services/vision_app/automation_runtime.py': '', 'backend/app/services/vision_app/endpoint_registry.py': '', 'backend/tests/vision_app/test_vision_app_v1100.py': '', 'frontend/docs/llm_context/updates/v1100_computer_vision_automation_ide.md': '', 'frontend/src/components/ComputerVision/AutomationIdeWorkspace.tsx': ''}

MODIFIED = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in MODIFIED_B64.items()
}
CREATED = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATED_B64.items()
}


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []

    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())

    fe_candidates += [
        cwd,
        cwd / "LambdaVisionSuper",
        cwd.parent / "LambdaVisionSuper",
    ]
    be_candidates += [
        cwd,
        cwd / "LambdaVisionSuperBackEnd",
        cwd.parent / "LambdaVisionSuperBackEnd",
    ]

    frontend = next(
        (
            p for p in fe_candidates
            if (p / "src/Pages/ComputerVisionPage.tsx").exists()
            and (p / "src/components/ComputerVision/DebugWorkspace.tsx").exists()
        ),
        None,
    )
    backend = next(
        (
            p for p in be_candidates
            if (p / "app/services/vision_app/runtime.py").exists()
            and (p / "app/api/v1/endpoints/vision_app_api.py").exists()
        ),
        None,
    )

    if frontend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuper frontend. "
            "Use --frontend /path/to/LambdaVisionSuper"
        )
    if backend is None:
        raise RuntimeError(
            "Cannot locate LambdaVisionSuperBackEnd. "
            "Use --backend /path/to/LambdaVisionSuperBackEnd"
        )
    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def modified_state(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    if path.read_text(encoding="utf-8") == desired:
        return "OK"
    return "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 108)
    print("COMPUTER VISION V0.11.0 — AUTOMATION IDE / CONTROL PLANE FOUNDATION")
    print("=" * 108)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()

    conflicts = 0
    for virtual, payload in MODIFIED.items():
        state = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1

    print()
    print("v0.11 foundation:")
    print("  Endpoint Registry: typed state / action / event / data namespaces")
    print("  Safe DSL: restricted AST, no exec/import/while/filesystem/subprocess")
    print("  Automation services: Loop / Event / One-shot")
    print("  VisionRunSnapshot: immutable Global/ROI Logic outputs per run")
    print("  Lifecycle: run_started -> logic_ready -> commit_result -> run_finish")
    print("  Dry Run suppresses physical side effects")
    print("  Execution Trace + Variables + Problems panels")
    print("  Registry-backed IDE completion + Endpoint Explorer")
    print("  Manual/test images synchronize into backend latest-frame state")
    print("  Existing Control Mapper / Trigger Runner / legacy v2 Decision stay compatible")
    print("  LLM context generator + v0.11 architecture handoff MD included")

    if conflicts:
        print()
        print(f"[WARN] {conflicts} conflict/base issue(s). apply will stop safely.")
    return 0


def preflight(frontend: Path, backend: Path):
    errors = []

    for virtual, payload in MODIFIED.items():
        state = modified_state(
            real_path(frontend, backend, virtual),
            payload["old"],
            payload["new"],
        )
        if state not in {"UPDATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")

    if errors:
        raise RuntimeError(
            "Safe update stopped:\n  - " + "\n  - ".join(errors)
        )


def backup(frontend: Path, backend: Path, paths: list[Path]) -> Path:
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    root = (
        frontend
        / ".lambda_updater_backups"
        / f"computer_vision_v1100_{stamp}"
    )
    root.mkdir(parents=True, exist_ok=True)

    for path in paths:
        if not path.exists():
            continue
        try:
            rel = path.relative_to(frontend)
            destination = root / "frontend" / rel
        except ValueError:
            rel = path.relative_to(backend)
            destination = root / "backend" / rel

        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, destination)

    return root


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    if not generator.exists():
        print("[SKIP] Context generator not found")
        return

    cmd = [
        sys.executable,
        str(generator),
        "--frontend",
        str(frontend),
        "--backend",
        str(backend),
    ]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(
            [
                "--output-dir",
                str(frontend / "docs/llm_context"),
            ]
        )

    proc = subprocess.run(
        cmd,
        cwd=str(frontend),
        text=True,
        capture_output=True,
    )
    if proc.returncode != 0:
        raise RuntimeError(
            "Context generator failed:\n"
            + (proc.stdout + "\n" + proc.stderr).strip()
        )

    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend, backend)

    targets = [
        real_path(frontend, backend, key)
        for key in list(MODIFIED) + list(CREATED)
    ]
    backup_root = backup(frontend, backend, targets)

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        if path.read_text(encoding="utf-8") != payload["new"]:
            path.write_text(payload["new"], encoding="utf-8")
            print(f"[WRITE] {virtual}")

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] {virtual}")

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)

    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def python_syntax(backend: Path):
    failures = []
    files = []

    for virtual in list(MODIFIED) + list(CREATED):
        if virtual.startswith("backend/") and virtual.endswith(".py"):
            path = real_path(Path("/unused"), backend, virtual)
            files.append(path)
            try:
                py_compile.compile(str(path), doraise=True)
            except Exception as exc:
                failures.append(
                    f"{path.relative_to(backend)}: {exc}"
                )
    return len(files), failures


def typescript_transpile(frontend: Path):
    files = [
        real_path(frontend, Path("/unused"), virtual)
        for virtual in list(MODIFIED) + list(CREATED)
        if virtual.startswith("frontend/")
        and virtual.endswith((".ts", ".tsx"))
    ]

    code = r"""
const fs = require("fs");
const ts = require("typescript");
let failed = false;

for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, "utf8");
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });

  const errors = (result.diagnostics || []).filter(
    (d) => d.category === ts.DiagnosticCategory.Error,
  );

  if (errors.length) {
    failed = true;
    console.error("TS_ERROR", file);
    for (const d of errors) {
      console.error(
        ts.flattenDiagnosticMessageText(d.messageText, "\n"),
      );
    }
  }
}
process.exit(failed ? 1 : 0);
"""

    env = dict(os.environ)
    npm_root = subprocess.run(
        ["npm", "root", "-g"],
        text=True,
        capture_output=True,
    )
    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (
            os.pathsep + env["NODE_PATH"]
            if env.get("NODE_PATH")
            else ""
        )

    return subprocess.run(
        ["node", "-e", code, *map(str, files)],
        cwd=str(frontend),
        env=env,
        text=True,
        capture_output=True,
    )


def backend_smoke(backend: Path):
    code = r"""
import numpy as np

from app.services.vision_app.automation_manager import AutomationManager
from app.services.vision_app.automation_models import (
    AutomationConfig,
    AutomationServiceDefinition,
)
from app.services.vision_app.automation_runtime import validate_script
from app.services.vision_app.models import (
    BenchmarkStep,
    ScopeRunResult,
    ServiceExecutionResult,
    VisionProgramDefinition,
    VisionProgramRunResult,
)


class FakeRepo:
    def __init__(self, program):
        self.program = program

    def get(self, _):
        return self.program

    def load_master(self, _):
        return np.zeros((32, 48, 3), dtype=np.uint8)


class FakeRuntime:
    def run_test(self, program, master, image):
        logic = ServiceExecutionResult(
            binding_id="logic",
            service_id="sampling",
            alias="measurement",
            ok=True,
            outputs={"score": 0.85},
        )
        scope = ScopeRunResult(
            scope_id="global",
            scope_name="Global",
            ok=True,
            logic_services=[logic],
        )
        return VisionProgramRunResult(
            program_id=program.program_id,
            run_id="smoke-run",
            global_ok=True,
            overall_ok=False,
            global_scope=scope,
            benchmarks=[
                BenchmarkStep(
                    scope="program",
                    phase="total",
                    name="Total",
                    elapsed_ms=2.0,
                )
            ],
            total_ms=2.0,
        )


class FakeCamera:
    def capture(self, _):
        return np.zeros((32, 48, 3), dtype=np.uint8)


class FakeIO:
    def __init__(self):
        self.writes = []

    def read_point(self, config, kind, address):
        return True

    def set_coil(self, config, address, value):
        self.writes.append((address, bool(value)))

    def pulse_result(self, config, ok, seconds=None):
        self.writes.append(("pulse", ok))


assert validate_script("import os")
assert not validate_script(
    "if device.modbus_1.X1 == ON:\n"
    "    system.commit_result(OK)\n"
)

judge = AutomationServiceDefinition(
    service_id="judge",
    name="Judge",
    mode="event",
    event="vision.logic_ready",
    script=(
        "if vision.global_scope.logic.measurement.outputs.score > 0.5:\n"
        "    system.commit_result(OK)\n"
        "else:\n"
        "    system.commit_result(NG)\n"
    ),
)
dry = AutomationServiceDefinition(
    service_id="dry",
    name="Dry",
    mode="oneshot",
    script="device.modbus_1.Y1 = ON\n",
)

program = VisionProgramDefinition(
    program_id="smoke",
    name="Smoke",
    automation=AutomationConfig(services=[judge, dry]),
)

io = FakeIO()
manager = AutomationManager(
    FakeRepo(program),
    FakeRuntime(),
    FakeCamera(),
    io,
)

run = manager.run_inspection(
    "smoke",
    np.zeros((32, 48, 3), dtype=np.uint8),
)
assert run.overall_ok is True
assert manager.state("smoke").result == "OK"

execution = manager.run_service(
    "smoke",
    "dry",
    dry_run=True,
)
assert execution.ok
assert io.writes == []

paths = {
    item["path"]
    for item in manager.catalog("smoke")
}
assert "system.run_inspection" in paths
assert "device.modbus_1.X1" in paths
assert (
    "vision.global_scope.logic.measurement.outputs.score"
    in paths
)

print(
    "AUTOMATION_V1100_SMOKE_OK",
    manager.state("smoke").result,
    len(manager.trace("smoke")),
    len(paths),
)
"""

    return subprocess.run(
        [sys.executable, "-c", code],
        cwd=str(backend),
        text=True,
        capture_output=True,
    )


def verify(frontend: Path, backend: Path, *, skip_build: bool = False):
    print("=" * 108)
    print("VERIFY COMPUTER VISION V0.11.0 — AUTOMATION IDE")
    print("=" * 108)

    failures = 0

    page = (
        frontend
        / "src/Pages/ComputerVisionPage.tsx"
    ).read_text(encoding="utf-8")
    api_ts = (
        frontend
        / "src/api/visionAppApi.ts"
    ).read_text(encoding="utf-8")
    models = (
        backend
        / "app/services/vision_app/models.py"
    ).read_text(encoding="utf-8")
    api_py = (
        backend
        / "app/api/v1/endpoints/vision_app_api.py"
    ).read_text(encoding="utf-8")
    automation_runtime = (
        backend
        / "app/services/vision_app/automation_runtime.py"
    ).read_text(encoding="utf-8")
    automation_manager = (
        backend
        / "app/services/vision_app/automation_manager.py"
    ).read_text(encoding="utf-8")
    endpoint_registry = (
        backend
        / "app/services/vision_app/endpoint_registry.py"
    ).read_text(encoding="utf-8")
    ide = (
        frontend
        / "src/components/ComputerVision/AutomationIdeWorkspace.tsx"
    ).read_text(encoding="utf-8")

    checks = [
        (
            "Program persists Automation services",
            "automation: AutomationConfig" in models
            and "services: list[AutomationServiceDefinition]"
            in (
                backend
                / "app/services/vision_app/automation_models.py"
            ).read_text(encoding="utf-8"),
        ),
        (
            "Endpoint Registry namespaces",
            "system.run_inspection" in endpoint_registry
            and "device.modbus_1.X1" in endpoint_registry
            and "vision.global_scope.logic" in endpoint_registry,
        ),
        (
            "Safe DSL has no exec",
            "ast.parse" in automation_runtime
            and "Unsupported syntax" in automation_runtime
            and "exec(" not in automation_runtime,
        ),
        (
            "Loop / Event / One-shot scheduler",
            'mode != "event"' in automation_manager
            and 's.mode == "loop"' in automation_manager
            and "run_service" in automation_manager,
        ),
        (
            "VisionRunSnapshot feeds Logic endpoints",
            "_snapshot_from_run" in automation_manager
            and "global_logic" in automation_manager
            and "roi_logic" in automation_manager,
        ),
        (
            "logic_ready / run_finish lifecycle",
            '"vision.logic_ready"' in automation_manager
            and '"system.run_finish"' in automation_manager
            and "commit_result" in automation_manager,
        ),
        (
            "Dry Run suppresses endpoint side effects",
            "if not dry_run" in automation_manager
            and "dry_run" in automation_runtime,
        ),
        (
            "Automation API endpoints installed",
            "/automation/endpoints" in api_py
            and "/automation/services/{service_id}/run" in api_py
            and "/automation/trace" in api_py,
        ),
        (
            "Manual/test image bridge installed",
            "automationSetLatestFrame" in api_ts
            and "automation_set_latest_frame" in api_py,
        ),
        (
            "Automation IDE module installed",
            "AutomationIdeWorkspace" in page
            and "Automation IDE" in page,
        ),
        (
            "Registry-backed completion / Endpoint Explorer",
            "Ctrl+Space" in ide
            and "ENDPOINT EXPLORER" in ide
            and "insertSuggestion" in ide,
        ),
        (
            "Validate / Dry Run / Run Service / Scheduler controls",
            "Dry Run" in ide
            and "Run Service" in ide
            and "Start Scheduler" in ide
            and "Validate" in ide,
        ),
        (
            "Trace / Problems / Variables panels",
            "EXECUTION TRACE" in ide
            and "PROBLEMS" in ide
            and "VARIABLES" in ide,
        ),
        (
            "v0.11 regression test installed",
            (
                backend
                / "tests/vision_app/test_vision_app_v1100.py"
            ).exists(),
        ),
        (
            "v0.11 handoff MD installed",
            (
                frontend
                / "docs/llm_context/updates/"
                / "v1100_computer_vision_automation_ide.md"
            ).exists(),
        ),
        (
            "Context generator knows Automation control plane",
            "Endpoint Registry" in (
                frontend
                / "tools/generate_llm_context_map.py"
            ).read_text(encoding="utf-8")
            and "Automation IDE" in (
                frontend
                / "tools/generate_llm_context_map.py"
            ).read_text(encoding="utf-8"),
        ),
    ]

    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    count, syntax_failures = python_syntax(backend)
    if syntax_failures:
        print("[FAIL] Python syntax")
        for issue in syntax_failures:
            print("  -", issue)
        failures += len(syntax_failures)
    else:
        print(
            f"[OK] Python syntax "
            f"({count} changed/new backend files)"
        )

    smoke = backend_smoke(backend)
    if smoke.returncode == 0:
        print("[OK] Automation backend smoke")
        if smoke.stdout.strip():
            print(smoke.stdout.strip())
    else:
        print("[FAIL] Automation backend smoke")
        print(
            (
                smoke.stdout
                + "\n"
                + smoke.stderr
            ).strip()
        )
        failures += 1

    if (
        importlib.util.find_spec("pytest") is not None
        and (backend / "tests/vision_app").exists()
    ):
        proc = subprocess.run(
            [
                sys.executable,
                "-m",
                "pytest",
                "-q",
                "tests/vision_app",
            ],
            cwd=str(backend),
            text=True,
            capture_output=True,
        )

        if proc.returncode == 0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print(
                (
                    proc.stdout
                    + "\n"
                    + proc.stderr
                ).strip()
            )
            failures += 1
    else:
        print("[SKIP] pytest / Vision App tests unavailable")

    ts = typescript_transpile(frontend)
    ts_text = (
        ts.stdout
        + "\n"
        + ts.stderr
    ).strip()

    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    elif (
        "Cannot find module 'typescript'" in ts_text
        or "MODULE_NOT_FOUND" in ts_text
    ):
        print("[SKIP] TypeScript module unavailable to Node")
    else:
        print("[FAIL] TypeScript syntax/transpile")
        print(ts_text)
        failures += 1

    if (
        not skip_build
        and (frontend / "package.json").exists()
        and (frontend / "node_modules").exists()
    ):
        proc = subprocess.run(
            ["npm", "run", "build"],
            cwd=str(frontend),
        )
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    try:
        regenerate_context(frontend, backend)
        arch = (
            frontend
            / "docs/llm_context/SYSTEM_ARCHITECTURE.md"
        )
        bundles = (
            frontend
            / "docs/llm_context/SYSTEM_CONTEXT_BUNDLES.md"
        )

        ok = (
            arch.exists()
            and bundles.exists()
            and "Automation" in arch.read_text(
                encoding="utf-8"
            )
        )
        print(
            f"[{'OK' if ok else 'FAIL'}] "
            "Regenerated Automation architecture/context"
        )
        failures += 0 if ok else 1
    except Exception as exc:
        print(
            f"[FAIL] Context regeneration: {exc}"
        )
        failures += 1

    if failures:
        print(
            f"[FAIL] v0.11.0 verification finished "
            f"with {failures} issue(s)."
        )
        return 1

    print(
        "[OK] Computer Vision v0.11.0 "
        "Automation IDE foundation verified."
    )
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "command",
        choices=["scan", "apply", "verify"],
    )
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument(
        "--skip-build",
        action="store_true",
    )
    args = parser.parse_args()

    try:
        frontend, backend = resolve_roots(
            args.frontend,
            args.backend,
        )

        if args.command == "scan":
            return scan(frontend, backend)

        if args.command == "apply":
            return apply(frontend, backend)

        return verify(
            frontend,
            backend,
            skip_build=args.skip_build,
        )
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
